CREATE OR REPLACE FUNCTION public.publish_monitor_publish_reconcile_claim(p_limit integer, p_lease_seconds integer, p_release_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
