 END IF;
 WITH due AS (
  SELECT id FROM social_publish_jobs WHERE (lease_until IS NULL OR lease_until<=clock_timestamp()) AND NOT manual_review
   AND ((state='claimed' AND claim_expires_at<=clock_timestamp())
